// Five octaves of noise `patchSize` mm across: where it is in the top `coverage`, rust -- its
// shade varying on a fifth of that -- not a metal any more, rough and with a plain coat.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let f = 0.5 + 0.5 * fbm3(q / patchSize, 21u, 5u, 2.0, 0.5).w;
let r = smoothstep(1.0 - coverage - softness, 1.0 - coverage + softness, f);
let tone = 0.5 + 0.5 * vnoise3(q / (0.2 * patchSize), 22u).w;
m.baseColor = mix(m.baseColor, mix(rust, rustLight, tone), r);
m.metallic = m.metallic * (1.0 - r);
m.roughness = mix(m.roughness, rustRough, r);
m.specular = mix(m.specular, 0.5, r);

children.code:
// A capped cone along z: base radius at the bottom, top radius at the top.
// No analytic normal (sdCappedCone): the renderer takes one by differences.
C = add_new(C, sdCappedCone(p, height * 0.5, base, top), MATERIAL);

// Repeat: copies "spacing" apart, "count" each way along each axis (0: not along it),
// so 2 count + 1 per axis -- all for the price of one, which makes it the cheapest
// thing here. The children must fit in one cell, half a spacing around this group's
// origin, or the distance is wrong near the cell borders.
p = p - spacing * clamp(round(p / spacing), -count, count);
C = children(C, p);

// Shell: the children's surface as a skin "thickness" thick, hollow inside -- cut it
// open with a subtract group to see in. Free per step; a Hit of their own, as round.
var H = children(emptyHit(r), p);
H.s = VEC4(H.s.xyz * sign(H.s.w), abs(H.s.w) - thickness * XF_S);
C = fold(C, H.s, H.m);

// A spherical lens along z (sdf.js Nlens): r1 the +z face, r2 the -z face; a positive radius
// bulges out, a negative one is hollowed in, 0 is flat. Its refractive index is its material's --
// give it a glass. Thin lens: 1/f = (n - 1)(1/r1 + 1/r2).
C = add_new(C, Nlens(p, diameter, thickness, r1, r2), MATERIAL);

// Shell: the children's surface as a skin "thickness" thick, hollow inside -- cut it
// open with a subtract group to see in. Free per step; a Hit of their own, as round.
var H = children(emptyHit(r), p);
H.s = VEC4(H.s.xyz * sign(H.s.w), abs(H.s.w) - thickness * XF_S);
C = fold(C, H.s, H.m);

